action_details.action_postfix:
taxpayer.military_retirement_pay /result.hi_military_retirement_exclusion xdef


taxpayer.sbp_payments 0 gt
{
  taxpayer.sbp_payments /result.hi_sbp_exclusion xdef
} if


taxpayer.military_drill_pay 0 gt
{
  taxpayer.military_drill_pay result.hi_guard_reserve_limit min
  /result.hi_guard_reserve_exclusion xdef
} if


result.hi_military_retirement_exclusion result.hi_sbp_exclusion add result.hi_guard_reserve_exclusion add
/result.hi_total_military_exclusion xdef


result.agi result.hi_total_military_exclusion sub 0 max
/result.hi_adjusted_agi xdef


"Hawaii military retirement exclusion: $" result.hi_military_retirement_exclusion cvs strconcat job.audit_trail swap addto
result.hi_sbp_exclusion 0 gt
{
  "Hawaii SBP exclusion: $" result.hi_sbp_exclusion cvs strconcat job.audit_trail swap addto
} if
result.hi_guard_reserve_exclusion 0 gt
{
  "Hawaii Guard/Reserve pay exclusion (up to $8,636): $" result.hi_guard_reserve_exclusion cvs strconcat job.audit_trail swap addto
} if
"Hawaii total military exclusion: $" result.hi_total_military_exclusion cvs strconcat job.audit_trail swap addto
